import { describe, expect, it } from "vitest";

import { findScheduleConflicts } from "../src/scheduleConflict";
import { scheduleConflictSections as s } from "../src/data";

describe("findScheduleConflicts", () => {
  it("flags a genuine overlap on shared days", () => {
    const conflicts = findScheduleConflicts([s.lectureMWF9], s.overlapMWF930);
    expect(conflicts.map((c) => c.section.sectionId)).toEqual([
      s.lectureMWF9.sectionId,
    ]);
  });

  it("does not flag the same time on different days", () => {
    const conflicts = findScheduleConflicts([s.lectureMWF9], s.lectureTTh9);
    expect(conflicts).toEqual([]);
  });

  it("does not flag back-to-back meetings (end === start)", () => {
    // lectureMWF9 ends at minute 590; lectureMWF10 starts at minute 590.
    const conflicts = findScheduleConflicts([s.lectureMWF9], s.lectureMWF10);
    expect(conflicts).toEqual([]);
  });

  it("checks every meeting of a multi-meeting section, not just the first", () => {
    // labTueThu meets Tue 14:00-15:00 AND Thu 14:00-15:00. overlapThuOnly
    // only overlaps the THURSDAY meeting. A implementation that only
    // inspects the first meeting in the array would miss this.
    const conflicts = findScheduleConflicts([s.labTueThu], s.overlapThuOnly);
    expect(conflicts.map((c) => c.section.sectionId)).toEqual([
      s.labTueThu.sectionId,
    ]);
  });

  it("returns no conflicts when nothing overlaps", () => {
    const conflicts = findScheduleConflicts(
      [s.lectureMWF9, s.lectureMWF10],
      s.labTueThu
    );
    expect(conflicts).toEqual([]);
  });

  it("only returns the enrolled sections that actually conflict, out of several", () => {
    // Enrolled in three sections; the candidate only overlaps lectureMWF9.
    const conflicts = findScheduleConflicts(
      [s.lectureMWF9, s.lectureTTh9, s.labTueThu],
      s.overlapMWF930
    );
    expect(conflicts).toHaveLength(1);
    expect(conflicts[0].section.sectionId).toBe(s.lectureMWF9.sectionId);
  });

  it("returns an empty array when the student has no enrolled sections", () => {
    const conflicts = findScheduleConflicts([], s.overlapMWF930);
    expect(conflicts).toEqual([]);
  });
});
